-- K-MAPS SEED — qr_ss_occ_sentence — Surah 12:1-7
INSERT OR IGNORE INTO qr_ss_occ_sentence
  (id, surah, ayah_from, ayah_to, sentence_kind, note_md)
VALUES
  ('7df8942d8a7c1df2fbbb002601', 12, 1, 1, 'nominal', 'Mode: khabariyya. افتتاح بالحروف المقطعة، يتلوه استئناف بجملة اسمية خبرية: مبتدأ (اسم إشارة) + خبر مركب إضافي، يتضمن نعتًا تابعًا للمضاف إليه'),
  ('5cd709aa4b41046f9212f8d2d6', 12, 2, 2, 'nominal', 'Mode: khabariyya. جملة اسمية مؤكدة بإنّ. اسم إنّ يقوم مقام المبتدأ، وخبرها جملة فعلية، يتبعها بيان المفعول والنعت، ثم جملة غاية تعليلية بلعلّ'),
  ('cf9b66f1cf1c896a36dce6ddd5', 12, 3, 3, 'verbal', 'Mode: khabariyya. جملة فعلية مُؤكَّدة بضمير الفصل/التوكيد (نحن) ثم فعل (نقص) ومتمماته، يتلوها تعليل/بيان بواسطة (بما) مع (ما الموصولة) وصلتها، ثم استئناف/حال تقريري بـ (وإن كنت...) مع لام الابتداء في الخبر (لمن الغافلين)'),
  ('d6912d9293a1aaa10b4d96c72d', 12, 4, 4, 'verbal', 'Mode: khabariyya. افتتاح ظرفي مشهدي بـ(إذ) يَدخل على فعل القول، ثم مقول قول طويل يتضمن: نداء (يا أبت)، وجملة إنّ (إني رأيت...) ثم عطف عناصر الرؤيا (والشمس والقمر)، ثم جملة فعلية ثانية (رأيتهم) مع (لي) وتأكيد هيئة الفعل (ساجدين)'),
  ('21e37a87c8d8e9ff8716f925b7', 12, 5, 5, 'verbal', 'Mode: khabariyya_with_insha_nahy_inside_quote. فعل قول يفتح مقولًا: نداء (يا بني) ثم نهي (لا تقصص) مع مفعول وجرّ ومجرور، ثم فاء/فاء السببية (فـيكيدوا) لبيان العاقبة المتوقعة، ثم تعليل/تقرير مستقل بجملة إنّ: (إن الشيطان للإنسان عدو مبين) مع لام الاختصاص/التعلق (للإنسان) ونعت (مبين)'),
  ('908162b206cf5e3e790aee8380', 12, 6, 6, 'verbal', 'Mode: khabariyya. افتتاح رابط (و + كذلك) يربط بالوعد السابق، ثم سلسلة أفعال معطوفة على محور واحد (يجتبيك/يعلمك/يتم) لبيان حزمة النعم. بعدها (كما) للتثبيت بالمثال التاريخي (أتمها على أبويك من قبل إبراهيم وإسحاق). ثم استئناف ختامي بجملة إنّ: (إن ربك عليم حكيم) تعليلًا للثقة بالوعد'),
  ('cc4cfa22a227cacc59a408a042', 12, 7, 7, 'nominal', 'Mode: khabariyya. توكيد مركّب (لـ + قد) مع كان الناقصة، وتقديم شبه الجملة (في يوسف وإخوته) لتوجيه الانتباه إلى موضع العبرة، ثم الخبر (آيات) مع جار ومجرور للغرض/الاختصاص (للسائلين)');

