  ('903fdcf45eb8fb802db4249e4f', 'cf9b66f1cf1c896a36dce6ddd5', '054fb459b1f2a7695ab67db3d6', 4, 12, 3, 3, 'nominal_predicate', 'adjunct', 'كنت', 'جملة كان وأخواتها: (كنت) + شبه جملة (من قبله) + خبر (لمن الغافلين).'),
  ('0493c597169a242602658796c0', 'd6912d9293a1aaa10b4d96c72d', NULL, 1, 12, 4, 4, 'main', 'predicate', 'إذ', 'مفتاح المشهد الزمني: إذ + قال + الفاعل + المتعلَّق (لأبيه).'),
