  ('e9a808019bfe24da3b75d8808c', 'd6912d9293a1aaa10b4d96c72d', 'c040dcc7ce037c4aa021bab5fa', 3, 12, 4, 4, 'vocative', NULL, 'يا', 'نداء عاطفي (يا أبت) يهيّئ لسرد الرؤيا.'),
  ('65f5fde7360d506897a14e32dd', 'd6912d9293a1aaa10b4d96c72d', 'c040dcc7ce037c4aa021bab5fa', 4, 12, 4, 4, 'nominal_subject', 'subject', 'إني', 'جملة إنّ: توكيد + فعل رؤية + المفعول (أحد عشر كوكبًا).'),
