  ('29fad36678537d9f50dfa9c5f1', '21e37a87c8d8e9ff8716f925b7', '3509c1b3bc4783614582db0935', 4, 12, 5, 5, 'nominal_subject', 'subject', 'لا', 'النهي الأساسي: لا تقصص رؤياك على إخوتك.'),
